package Buffer

import (
	"encoding/binary"
)

// This half holds the Recv, Fire block(s). Row blocks are split across two files
// purely to stay under check-file-size.sh's limit — the division is by position in
// Buffer/bufschema/layout.go, not by meaning, so neither file is a category.

// ── Recv block ───────────────────────────────────────────────
const (
	BufRecvColNodeRow = 0 // i32
	BufRecvColValue   = 4 // i32
	BufRecvStride     = 8
)

// SetRecvRow writes one Recv row into buf[row*BufRecvStride:].
func SetRecvRow(buf []byte, row int, nodeRow int32, value int32) {
	off := row * BufRecvStride
	binary.LittleEndian.PutUint32(buf[off+0:], uint32(nodeRow))
	binary.LittleEndian.PutUint32(buf[off+4:], uint32(value))
}

// ── Fire block ───────────────────────────────────────────────
const (
	BufFireColNodeRow = 0 // i32
	BufFireStride     = 4
)

// SetFireRow writes one Fire row into buf[row*BufFireStride:].
func SetFireRow(buf []byte, row int, nodeRow int32) {
	off := row * BufFireStride
	binary.LittleEndian.PutUint32(buf[off+0:], uint32(nodeRow))
}
